const rawText = $input.first().json.content.parts[0].text;
const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
const audit = JSON.parse(cleaned);
return [{ json: audit }];

const d = $input.first().json;
const docType = $('Draft Intake Form').first().json['Document Type'];
const risks = (d.risk_reasons || []).map(r => `- ${r}`).join('\n');
const slop = (d.slop_removed || []).map(s => `- ${s}`).join('\n');

const report = [
  `STATUS: FLAGGED FOR COMPLIANCE REVIEW (${docType})`,
  ``,
  `RISK REASONS:`,
  risks || '- None listed',
  ``,
  `SLOP REMOVED:`,
  slop || '- None listed',
  ``,
  `CLEAN REWRITE:`,
  d.clean_rewrite
].join('\n');

return [{
  json: {
    status: 'FLAGGED_FOR_REVIEW',
    document_type: docType,
    formatted_report: report
  }
}];

const d = $input.first().json;
const docType = $('Draft Intake Form').first().json['Document Type'];

const report = [
  `STATUS: CLEARED FOR USE (${docType})`,
  ``,
  `CLEAN TEXT:`,
  d.clean_rewrite
].join('\n');

return [{
  json: {
    status: 'CLEARED',
    document_type: docType,
    formatted_report: report
  }
}];

